$sm=$_SESSION['user']['matricule']??'Utilisateur';$sn=trim($_SESSION['user']['nom_utilisateur']??'')?:$sm;$sp=$_SESSION['user']['profil']??'';$role=$_SESSION['user']['role']??'';$today=date('Y-m-d');$counts=['active'=>0,'upcoming'=>0,'ended'=>0];
foreach($affectations as $a){$state=$a['date_debut']>$today?'upcoming':(($a['date_fin']&&$a['date_fin']<$today)?'ended':'active');$counts[$state]++;}
