<?php foreach($affectations as $a):$full=trim(implode(' ',array_filter([$a['nom'],$a['postnom'],$a['prenom']])));$state=$a['date_debut']>$today?'upcoming':(($a['date_fin']&&$a['date_fin']<$today)?'ended':'active');$stateLabel=['active'=>'En cours','upcoming'=>'À venir','ended'=>'Terminée'][$state];$json=htmlspecialchars(json_encode($a),ENT_QUOTES,'UTF-8');$search=strtolower($a['immatriculation'].' '.$a['marque'].' '.$a['modele'].' '.$full.' '.$a['fonction_nom']);?><tr data-search="<?= htmlspecialchars($search) ?>" data-state="<?= $state ?>"><td><div class="assignment-vehicle"><i class="bi bi-truck-front"></i><div><strong><?= htmlspecialchars($a['immatriculation']) ?></strong><small><?= htmlspecialchars(trim(($a['marque']??'').' '.($a['modele']??''))?:'Véhicule') ?></small></div></div></td><td><div class="identity"><span><?php if($a['profil']):?><img src="<?= BASE_URL.'/'.htmlspecialchars($a['profil']) ?>" alt="Profil"><?php else:?><?= htmlspecialchars(strtoupper(substr($full,0,2))) ?><?php endif;?></span><div><strong><?= htmlspecialchars($full) ?></strong><small><?= htmlspecialchars($a['travailleur_matricule']) ?></small></div></div></td><td><span class="function-badge"><?= htmlspecialchars($a['fonction_nom']) ?></span></td><td><strong><?= date('d/m/Y',strtotime($a['date_debut'])) ?></strong><small class="assignment-muted">au <?= $a['date_fin']?date('d/m/Y',strtotime($a['date_fin'])):'Indéterminé' ?></small></td><td><span class="assignment-state state-<?= $state ?>"><?= $stateLabel ?></span></td><td><div class="row-actions"><button onclick="openAssignmentModal(<?= $json ?>)"><i class="bi bi-pencil"></i></button><button class="danger" onclick="openDeleteAssignment(<?= (int)$a['id'] ?>,'<?= htmlspecialchars($a['immatriculation'].' — '.$full,ENT_QUOTES) ?>')"><i class="bi bi-trash3"></i></button></div></td></tr><?php endforeach;?></tbody></table></div></section></div><div id="view-attributions" class="hidden"><section class="users-heading"><div><h2>Attributions de fonctions</h2><p>Définissez les responsabilités et le taux de rémunération de chaque travailleur.</p></div><button class="add-button" onclick="openRoleAssignmentModal()" <?= (!$travailleurs||!$fonctions)?'disabled':'' ?>><i class="bi bi-person-plus"></i> Attribuer une fonction</button></section><section class="users-toolbar"><label class="search-field"><i class="bi bi-search"></i><input id="role-search" type="search" placeholder="Travailleur ou fonction…" oninput="filterRoleAssignments()"></label><span id="role-count"><?= count($attributionsFonctions) ?> attribution(s)</span></section><section class="users-table-card"><div class="users-table-scroll"><table><thead><tr><th>Travailleur</th><th>Fonction</th><th>Taux de rémunération</th><th>Statut</th><th>Création</th><th></th></tr></thead><tbody id="roles-body"><?php if(!$attributionsFonctions):?><tr><td colspan="6" class="users-empty"><i class="bi bi-person-badge"></i><strong>Aucune fonction attribuée</strong><span>Attribuez une fonction à un travailleur actif.</span></td></tr><?php endif;?><?php foreach($attributionsFonctions as $af):$afName=trim(implode(' ',array_filter([$af['nom'],$af['postnom'],$af['prenom']])));$afJson=htmlspecialchars(json_encode($af),ENT_QUOTES,'UTF-8');?><tr data-search="<?= htmlspecialchars(strtolower($afName.' '.$af['matricule'].' '.$af['fonction_nom'])) ?>"><td><div class="identity"><span><?php if($af['profil']):?><img src="<?= BASE_URL.'/'.htmlspecialchars($af['profil']) ?>" alt="Profil"><?php else:?><?= htmlspecialchars(strtoupper(substr($afName,0,2))) ?><?php endif;?></span><div><strong><?= htmlspecialchars($afName) ?></strong><small><?= htmlspecialchars($af['matricule']) ?></small></div></div></td><td><span class="function-badge"><?= htmlspecialchars($af['fonction_nom']) ?></span></td><td><?= $af['taux_remuneration']!==null?number_format((float)$af['taux_remuneration'],2,',',' ').' %':'—' ?></td><td><span class="assignment-state <?= $af['statut']==='ACTIF'?'state-active':'state-ended' ?>"><?= $af['statut']==='ACTIF'?'Active':'Suspendue' ?></span></td><td><?= date('d/m/Y',strtotime($af['created_at'])) ?></td><td><div class="row-actions"><button onclick="openRoleAssignmentModal(<?= $afJson ?>)"><i class="bi bi-pencil"></i></button><?php if($af['statut']==='ACTIF'):?><button class="danger" onclick="openDeleteRoleAssignment(<?= (int)$af['id'] ?>,'<?= htmlspecialchars($afName.' — '.$af['fonction_nom'],ENT_QUOTES) ?>')"><i class="bi bi-pause-circle"></i></button><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section></div></div><footer class="dashboard-footer">© <?= date('Y') ?> MWIRA Trans <span>Affectations et fonctions</span></footer></main></div>
