<div class="users-modal-overlay" id="assignment-modal"><div class="users-modal assignment-modal"><div class="modal-title"><div><h3 id="assignment-title">Nouvelle affectation</h3><p>Véhicule, travailleur et période</p></div><button onclick="closeModal('assignment-modal')">&times;</button></div><form method="POST" action="<?= BASE_URL ?>/affectations"><input type="hidden" name="action" id="assignment-action" value="create"><input type="hidden" name="id" id="assignment-id"><label>Véhicule *<select name="vehicule_id" id="vehicule_id" required><option value="">Sélectionner un véhicule</option><?php foreach($vehicules as $v):?><option value="<?= (int)$v['id'] ?>"><?= htmlspecialchars($v['immatriculation'].' — '.trim(($v['marque']??'').' '.($v['modele']??''))) ?></option><?php endforeach;?></select></label><label>Travailleur et fonction *<select name="attribution_id" id="attribution_id" required><option value="">Sélectionner une attribution</option><?php foreach($attributions as $a):$n=trim(implode(' ',array_filter([$a['nom'],$a['postnom'],$a['prenom']])));?><option value="<?= (int)$a['id'] ?>"><?= htmlspecialchars($n.' — '.$a['fonction_nom'].' ('.$a['matricule'].')') ?></option><?php endforeach;?></select></label><div class="assignment-form-grid"><label>Date de début *<input type="date" name="date_debut" id="date_debut" required></label><label>Date de fin<input type="date" name="date_fin" id="date_fin"><small>Laissez vide pour une durée indéterminée.</small></label><label class="full-field">Observation<textarea name="observation" id="observation" rows="3" maxlength="1000"></textarea></label></div><div class="modal-buttons"><button type="button" class="cancel" onclick="closeModal('assignment-modal')">Annuler</button><button type="submit" class="save"><i class="bi bi-check-lg"></i> Enregistrer</button></div></form></div></div>
<div class="users-modal-overlay" id="delete-assignment-modal"><div class="users-modal confirm-modal"><span class="warning-icon"><i class="bi bi-exclamation-triangle"></i></span><h3>Supprimer cette affectation ?</h3><p id="delete-assignment-name"></p><form method="POST" action="<?= BASE_URL ?>/affectations"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" id="delete-assignment-id"><div class="modal-buttons"><button type="button" class="cancel" onclick="closeModal('delete-assignment-modal')">Annuler</button><button class="delete-confirm">Supprimer</button></div></form></div></div>
<div class="users-modal-overlay" id="role-assignment-modal"><div class="users-modal"><div class="modal-title"><div><h3 id="role-assignment-title">Attribuer une fonction</h3><p>Responsabilité et rémunération du travailleur</p></div><button onclick="closeModal('role-assignment-modal')">&times;</button></div><form method="POST" action="<?= BASE_URL ?>/affectations"><input type="hidden" name="action" id="role-assignment-action" value="attribution_create"><input type="hidden" name="id" id="role-assignment-id"><label>Travailleur *<select name="travailleur_id" id="travailleur_id" required><option value="">Sélectionner un travailleur</option><?php foreach($travailleurs as $t):$tn=trim(implode(' ',array_filter([$t['nom'],$t['postnom'],$t['prenom']])));?><option value="<?= (int)$t['id'] ?>"><?= htmlspecialchars($tn.' — '.$t['matricule']) ?></option><?php endforeach;?></select></label><label>Fonction *<select name="fonction_id" id="fonction_id" required><option value="">Sélectionner une fonction</option><?php foreach($fonctions as $f):?><option value="<?= (int)$f['id'] ?>"><?= htmlspecialchars($f['nom']) ?></option><?php endforeach;?></select></label><label>Taux de rémunération (%)<input type="number" name="taux_remuneration" id="taux_remuneration" min="0" step="0.01" placeholder="Ex. 15"><small>Pourcentage appliqué à cette fonction.</small></label><label>Statut<select name="statut" id="role_status"><option value="ACTIF">Active</option><option value="SUSPENDU">Suspendue</option></select></label><div class="modal-buttons"><button type="button" class="cancel" onclick="closeModal('role-assignment-modal')">Annuler</button><button type="submit" class="save"><i class="bi bi-check-lg"></i> Enregistrer</button></div></form></div></div>
<div class="users-modal-overlay" id="delete-role-assignment-modal"><div class="users-modal confirm-modal"><span class="warning-icon"><i class="bi bi-exclamation-triangle"></i></span><h3>Suspendre cette attribution ?</h3><p id="delete-role-assignment-name"></p><form method="POST" action="<?= BASE_URL ?>/affectations"><input type="hidden" name="action" value="attribution_delete"><input type="hidden" name="id" id="delete-role-assignment-id"><div class="modal-buttons"><button type="button" class="cancel" onclick="closeModal('delete-role-assignment-modal')">Annuler</button><button class="delete-confirm">Suspendre</button></div></form></div></div>
<link href="<?= BASE_URL ?>/assets/css/assignment-tabs.css" rel="stylesheet">
<link href="<?= BASE_URL ?>/assets/css/worker-choice.css" rel="stylesheet">
<script>
function switchAssignmentView(view){document.querySelectorAll('.module-breadcrumbs button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.getElementById('view-affectations').classList.toggle('hidden',view!=='affectations');document.getElementById('view-attributions').classList.toggle('hidden',view!=='attributions')}
function openAssignmentModal(a=null){document.getElementById('assignment-action').value=a?'update':'create';document.getElementById('assignment-id').value=a?.id||'';['vehicule_id','attribution_id','date_debut','date_fin','observation'].forEach(f=>document.getElementById(f).value=a?.[f]||'');document.getElementById('assignment-title').textContent=a?'Modifier l’affectation':'Nouvelle affectation';openModal('assignment-modal')}function filterAssignments(){const q=document.getElementById('assignment-search').value.toLowerCase().trim(),s=document.getElementById('assignment-state').value;let n=0;document.querySelectorAll('#assignments-body tr[data-search]').forEach(r=>{const show=(!q||r.dataset.search.includes(q))&&(!s||r.dataset.state===s);r.style.display=show?'':'none';if(show)n++});document.getElementById('assignment-count').textContent=n+' affectation(s)'}function openDeleteAssignment(id,n){document.getElementById('delete-assignment-id').value=id;document.getElementById('delete-assignment-name').textContent=n;openModal('delete-assignment-modal')}
function openRoleAssignmentModal(a=null){document.getElementById('role-assignment-action').value=a?'attribution_update':'attribution_create';document.getElementById('role-assignment-id').value=a?.id||'';document.getElementById('travailleur_id').value=a?.travailleur_id||'';document.getElementById('fonction_id').value=a?.fonction_id||'';document.getElementById('taux_remuneration').value=a?.taux_remuneration||'';document.getElementById('role_status').value=a?.statut||'ACTIF';document.getElementById('role-assignment-title').textContent=a?'Modifier l’attribution':'Attribuer une fonction';openModal('role-assignment-modal')}function filterRoleAssignments(){const q=document.getElementById('role-search').value.toLowerCase().trim();let n=0;document.querySelectorAll('#roles-body tr[data-search]').forEach(r=>{const show=!q||r.dataset.search.includes(q);r.style.display=show?'':'none';if(show)n++});document.getElementById('role-count').textContent=n+' attribution(s)'}function openDeleteRoleAssignment(id,n){document.getElementById('delete-role-assignment-id').value=id;document.getElementById('delete-role-assignment-name').textContent=n;openModal('delete-role-assignment-modal')}function openModal(id){document.getElementById(id).classList.add('show')}function closeModal(id){document.getElementById(id).classList.remove('show')}function toggleSidebar(){document.getElementById('dashboard-sidebar').classList.toggle('open');document.getElementById('mobile-overlay').classList.toggle('show')}setTimeout(()=>document.querySelector('.users-toast')?.remove(),4000);
const eligibleWorkers=<?= json_encode($travailleurs, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;
function workerName(w){return [w.nom,w.postnom,w.prenom].filter(Boolean).join(' ')}
function escapeWorkerHtml(value){const d=document.createElement('div');d.textContent=value||'';return d.innerHTML}
function renderWorkerChoices(current=null){const select=document.getElementById('travailleur_id');let grid=document.getElementById('worker-choice-grid');if(!grid){grid=document.createElement('div');grid.id='worker-choice-grid';grid.className='worker-choice-grid';select.parentNode.insertBefore(grid,select);select.classList.add('worker-select-hidden')}let workers=[...eligibleWorkers];if(current&&!workers.some(w=>String(w.id)===String(current.travailleur_id)))workers.unshift({id:current.travailleur_id,matricule:current.matricule,nom:current.nom,postnom:current.postnom,prenom:current.prenom,profil:current.profil});const selected=String(current?.travailleur_id||'');grid.innerHTML=workers.length?workers.map(w=>{const name=workerName(w),active=String(w.id)===selected,avatar=w.profil?`<img src="<?= BASE_URL ?>/${escapeWorkerHtml(w.profil)}" alt="">`:`<span>${escapeWorkerHtml(name.substring(0,2).toUpperCase())}</span>`;return `<button type="button" class="worker-choice ${active?'selected':''}" onclick="chooseWorker('${w.id}',this)"><span class="worker-choice-avatar">${avatar}</span><span><strong>${escapeWorkerHtml(name)}</strong><small>${escapeWorkerHtml(w.matricule)}</small></span><i class="bi bi-check-circle-fill"></i></button>`}).join(''):'<div class="no-worker-choice"><i class="bi bi-person-check"></i><span>Tous les travailleurs actifs ont déjà une attribution active.</span></div>';select.value=selected}
function chooseWorker(id,button){document.getElementById('travailleur_id').value=id;document.querySelectorAll('.worker-choice').forEach(b=>b.classList.remove('selected'));button.classList.add('selected')}
function openRoleAssignmentModal(a=null){document.getElementById('role-assignment-action').value=a?'attribution_update':'attribution_create';document.getElementById('role-assignment-id').value=a?.id||'';const workerSelect=document.getElementById('travailleur_id');if(a&&!Array.from(workerSelect.options).some(o=>String(o.value)===String(a.travailleur_id)))workerSelect.add(new Option(workerName(a),a.travailleur_id));renderWorkerChoices(a);document.getElementById('fonction_id').value=a?.fonction_id||'';document.getElementById('taux_remuneration').value=a?.taux_remuneration||'';document.getElementById('role_status').value=a?.statut||'ACTIF';document.getElementById('role-assignment-title').textContent=a?'Modifier l’attribution':'Attribuer une fonction';openModal('role-assignment-modal')}
</script></body></html>
